  /**
   * allFeaturesBackupFtpAccess iterates over GET /v1/dedicated/server/{serviceName}/features/backupFTP/access (List backup FTP ACLs).
   *
   * It lists the IDs with {@link DedicatedserverApi.listFeaturesBackupFtpAccess}, then gets each object with
   * {@link DedicatedserverApi.getFeaturesBackupFtpAccess}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action dedicatedServer:apiovh:features/backupFTP/access/get.
   *
   * @param serviceName - The internal name of your dedicated server
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.DedicatedServerBackupFtpACL}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.dedicatedserver.allFeaturesBackupFtpAccess(serviceName)) console.log(item);
   */
  allFeaturesBackupFtpAccess(
    serviceName: string,
    options?: RequestOptions,
  ): AsyncIterable<models.DedicatedServerBackupFtpACL> {
    return this._each(
      () => this.listFeaturesBackupFtpAccess(serviceName, options),
      (listedId) => this.getFeaturesBackupFtpAccess(serviceName, listedId, options),
    );
  }

